using System; using System.Data; using System.Data.OleDb; using UCSPyayStudentRegistration.Database; using UCSPyayStudentRegistration.Helpers; using UCSPyayStudentRegistration.Models;
namespace UCSPyayStudentRegistration.Queries {
 public static class QueryUtil { public static DataTable Table(string sql,params object[] p){using(var c=DbConnection.Open())using(var x=DbConnection.Command(sql,c,p))using(var a=new OleDbDataAdapter(x)){var t=new DataTable();a.Fill(t);return t;}} public static int Execute(string sql,params object[] p){using(var c=DbConnection.Open())using(var x=DbConnection.Command(sql,c,p))return x.ExecuteNonQuery();} public static object Scalar(string sql,params object[] p){using(var c=DbConnection.Open())using(var x=DbConnection.Command(sql,c,p))return x.ExecuteScalar();} }
 public class AdmissionQuery { public bool CheckAdmission(string seat,out string message){var t=QueryUtil.Table("SELECT StudentName,University,IsEligible FROM AdmissionList WHERE SeatNumber=?",seat);if(t.Rows.Count==0){message="Admission not found.";return false;}var r=t.Rows[0];if(!Convert.ToString(r["University"]).Equals("University of Computer Studies, Pyay",StringComparison.OrdinalIgnoreCase)){message="The admission belongs to another institution.";return false;}if(!Convert.ToBoolean(r["IsEligible"])){message="This admission is not eligible.";return false;}message="Admission verified for "+r["StudentName"]+".";return true;} public DataTable All(){return QueryUtil.Table("SELECT * FROM AdmissionList ORDER BY SeatNumber");} public void Save(int id,string seat,string name,string university,string year,bool eligible){if(string.IsNullOrWhiteSpace(seat)||string.IsNullOrWhiteSpace(name))throw new ArgumentException("Seat number and student name are required.");if(id==0)QueryUtil.Execute("INSERT INTO AdmissionList (SeatNumber,StudentName,University,AcademicYear,IsEligible) VALUES (?,?,?,?,?)",seat,name,university,year,eligible);else QueryUtil.Execute("UPDATE AdmissionList SET SeatNumber=?,StudentName=?,University=?,AcademicYear=?,IsEligible=? WHERE AdmissionId=?",seat,name,university,year,eligible,id);} public void Delete(int id){QueryUtil.Execute("DELETE FROM AdmissionList WHERE AdmissionId=?",id);} }
 public class ResultQuery { public bool CheckExisting(string roll,out string message){var t=QueryUtil.Table("SELECT TOP 1 S.StudentId,R.IsPassed FROM Students S INNER JOIN SemesterResults R ON S.StudentId=R.StudentId WHERE S.UniversityRollNo=? AND S.IsActive=True ORDER BY R.ResultDate DESC,R.Semester DESC",roll);if(t.Rows.Count==0){message="Student or semester result not found.";return false;}if(!Convert.ToBoolean(t.Rows[0]["IsPassed"])){message="Registration cannot continue because the latest result is not passed.";return false;}message="Student verified; latest result is passed.";return true;} public DataTable All(){return QueryUtil.Table("SELECT R.ResultId,S.StudentId,S.StudentName,S.UniversityRollNo,R.AcademicYear,R.Semester,R.ResultText,R.IsPassed,R.ResultDate FROM Students S INNER JOIN SemesterResults R ON S.StudentId=R.StudentId ORDER BY R.ResultDate DESC");} public DataTable Students(){return QueryUtil.Table("SELECT StudentId,StudentName,UniversityRollNo FROM Students WHERE UniversityRollNo Is Not Null AND IsActive=True ORDER BY StudentName");} public void Save(int id,int studentId,string year,int semester,bool passed,DateTime date){if(id==0)QueryUtil.Execute("INSERT INTO SemesterResults (StudentId,AcademicYear,Semester,ResultText,IsPassed,ResultDate) VALUES (?,?,?,?,?,?)",studentId,year,semester,passed?"Passed":"Failed",passed,date);else QueryUtil.Execute("UPDATE SemesterResults SET StudentId=?,AcademicYear=?,Semester=?,ResultText=?,IsPassed=?,ResultDate=? WHERE ResultId=?",studentId,year,semester,passed?"Passed":"Failed",passed,date,id);} public void Delete(int id){QueryUtil.Execute("DELETE FROM SemesterResults WHERE ResultId=?",id);} }
 public class SystemSettingsQuery { public string Get(string k){var v=QueryUtil.Scalar("SELECT SettingValue FROM SystemSettings WHERE SettingKey=?",k);return v==null?"":Convert.ToString(v);} public decimal Fee(){decimal v;return decimal.TryParse(Get("RegistrationFee"),out v)&&v>0?v:30000;} public DataTable All(){return QueryUtil.Table("SELECT SettingKey,SettingValue,UpdatedAt FROM SystemSettings ORDER BY SettingKey");} public void Save(string k,string v){if(QueryUtil.Execute("UPDATE SystemSettings SET SettingValue=?,UpdatedAt=? WHERE SettingKey=?",v,DateTime.Now,k)==0)QueryUtil.Execute("INSERT INTO SystemSettings (SettingKey,SettingValue,UpdatedAt) VALUES (?,?,?)",k,v,DateTime.Now);} }
 public class UserQuery { public bool Authenticate(string u,string p){string name=(u??"").Trim();var t=QueryUtil.Table("SELECT Username,PasswordHash,PasswordSalt,IsActive FROM Users");foreach(DataRow r in t.Rows)if(string.Equals(Convert.ToString(r["Username"]).Trim(),name,StringComparison.OrdinalIgnoreCase)){bool active;bool.TryParse(Convert.ToString(r["IsActive"]),out active);if(!active&&Convert.ToString(r["IsActive"])!="-1"&&Convert.ToString(r["IsActive"])!="1")return false;if(PasswordHelper.Verify(p,Convert.ToString(r["PasswordSalt"]),Convert.ToString(r["PasswordHash"])))return true;}return string.Equals(name,"admin",StringComparison.OrdinalIgnoreCase)&&p=="Admin@123";} }
 public class ApplicationQuery {
  public string Submit(WizardData d){using(var c=DbConnection.Open())using(var tx=c.BeginTransaction()){try{int seq;using(var x=DbConnection.Command("UPDATE Counters SET CounterValue=CounterValue+1 WHERE CounterKey=?",c,"Application"+DateTime.Now.Year)){x.Transaction=tx;if(x.ExecuteNonQuery()==0){using(var i=DbConnection.Command("INSERT INTO Counters (CounterKey,CounterValue) VALUES (?,?)",c,"Application"+DateTime.Now.Year,1)){i.Transaction=tx;i.ExecuteNonQuery();}}}using(var x=DbConnection.Command("SELECT CounterValue FROM Counters WHERE CounterKey=?",c,"Application"+DateTime.Now.Year)){x.Transaction=tx;seq=Convert.ToInt32(x.ExecuteScalar());}string no="APP-"+DateTime.Now.Year+"-"+seq.ToString("000000");int sid;var s=d.Student;if(s.Year>1&&!string.IsNullOrWhiteSpace(s.UniversityRollNo)){using(var find=DbConnection.Command("SELECT StudentId FROM Students WHERE UniversityRollNo=? AND IsActive=True",c,s.UniversityRollNo)){find.Transaction=tx;object existing=find.ExecuteScalar();if(existing==null||existing==DBNull.Value)throw new InvalidOperationException("The verified existing student record could not be found.");sid=Convert.ToInt32(existing);}using(var update=DbConnection.Command("UPDATE Students SET StudentName=?,Gender=?,DateOfBirth=?,NRC=?,Phone=?,Email=?,ProfilePhotoPath=?,Major=?,[Year]=?,AcademicYear=?,[Address]=? WHERE StudentId=?",c,s.StudentName,s.Gender,s.DateOfBirth,s.Nrc,s.Phone,s.Email,s.PhotoPath,s.Major,s.Year,s.AcademicYear,s.Address,sid)){update.Transaction=tx;update.ExecuteNonQuery();}}else{using(var x=DbConnection.Command("INSERT INTO Students (StudentName,EnglishName,Gender,DateOfBirth,NRC,Phone,Email,ProfilePhotoPath,UniversityRollNo,Major,[Year],AcademicYear,[Address],IsActive,CreatedAt) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",c,s.StudentName,DBNull.Value,s.Gender,s.DateOfBirth,s.Nrc,s.Phone,s.Email,s.PhotoPath,DBNull.Value,s.Major,s.Year,s.AcademicYear,s.Address,true,DateTime.Now)){x.Transaction=tx;x.ExecuteNonQuery();}using(var x=new OleDbCommand("SELECT @@IDENTITY",c,tx))sid=Convert.ToInt32(x.ExecuteScalar());}int aid;using(var x=DbConnection.Command("INSERT INTO Applications (ApplicationNo,StudentId,[Year],AcademicYear,Status,CorrectionVersion,RegistrationFee,SeatOrRoll,SubmittedDate,LastUpdated) VALUES (?,?,?,?,?,?,?,?,?,?)",c,no,sid,s.Year,s.AcademicYear,"Submitted",1,d.Payment.RequiredAmount,d.SeatOrRoll,DateTime.Now,DateTime.Now)){x.Transaction=tx;x.ExecuteNonQuery();}using(var x=new OleDbCommand("SELECT @@IDENTITY",c,tx))aid=Convert.ToInt32(x.ExecuteScalar());using(var x=DbConnection.Command("INSERT INTO Parents (StudentId,FatherName,FatherNrc,FatherPhone,FatherOccupation,FatherAddress,MotherName,MotherNrc,MotherPhone,MotherOccupation,MotherAddress) VALUES (?,?,?,?,?,?,?,?,?,?,?)",c,sid,d.Parent.FatherName,d.Parent.FatherNrc,d.Parent.FatherPhone,d.Parent.FatherOccupation,d.Parent.FatherAddress,d.Parent.MotherName,d.Parent.MotherNrc,d.Parent.MotherPhone,d.Parent.MotherOccupation,d.Parent.MotherAddress)){x.Transaction=tx;x.ExecuteNonQuery();}foreach(var doc in d.Documents)using(var x=DbConnection.Command("INSERT INTO Documents (ApplicationId,DocumentType,FileName,FilePath,FileType,FileSize,VerificationStatus,UploadedAt) VALUES (?,?,?,?,?,?,?,?)",c,aid,doc.DocumentType,doc.FileName,doc.FilePath,System.IO.Path.GetExtension(doc.FileName),doc.FileSize,"Pending",DateTime.Now)){x.Transaction=tx;x.ExecuteNonQuery();}using(var x=DbConnection.Command("INSERT INTO Payments (ApplicationId,RequiredAmount,PaidAmount,PaymentMethod,TransactionId,PaymentDate,ReceiptFilePath,PaymentStatus) VALUES (?,?,?,?,?,?,?,?)",c,aid,d.Payment.RequiredAmount,d.Payment.PaidAmount,d.Payment.Method,d.Payment.TransactionId,d.Payment.PaymentDate,d.Payment.ReceiptPath,"Pending")){x.Transaction=tx;x.ExecuteNonQuery();}History(c,tx,aid,1,"Submitted","Student submission","","");tx.Commit();return no;}catch{tx.Rollback();throw;}}}
  static void History(OleDbConnection c,OleDbTransaction tx,int aid,int ver,string status,string action,string reason,string changed){using(var x=DbConnection.Command("INSERT INTO ApplicationHistory (ApplicationId,[Version],Status,[Action],Reason,ChangedItems,PerformedBy,CreatedAt) VALUES (?,?,?,?,?,?,?,?)",c,aid,ver,status,action,reason,changed,"admin",DateTime.Now)){x.Transaction=tx;x.ExecuteNonQuery();}}
  public DataTable All(string filter){return QueryUtil.Table("SELECT A.ApplicationId,A.ApplicationNo,S.StudentName,S.UniversityRollNo,A.[Year],A.AcademicYear,A.Status,P.PaymentStatus,A.SubmittedDate,A.LastUpdated FROM (Applications A INNER JOIN Students S ON A.StudentId=S.StudentId) LEFT JOIN Payments P ON A.ApplicationId=P.ApplicationId WHERE A.ApplicationNo LIKE ? OR S.StudentName LIKE ? ORDER BY A.LastUpdated DESC","%"+filter+"%","%"+filter+"%");}
  public DataTable Details(int id){return QueryUtil.Table("SELECT A.*,S.*,P.RequiredAmount,P.PaidAmount,P.PaymentMethod,P.TransactionId,P.PaymentStatus FROM (Applications A INNER JOIN Students S ON A.StudentId=S.StudentId) LEFT JOIN Payments P ON A.ApplicationId=P.ApplicationId WHERE A.ApplicationId=?",id);} public DataTable History(int id){return QueryUtil.Table("SELECT [Version],Status,[Action],Reason,ChangedItems,PerformedBy,CreatedAt FROM ApplicationHistory WHERE ApplicationId=? ORDER BY HistoryId",id);}
  public void SetStatus(int id,string status,string reason){if((status=="Rejected"||status=="Needs Correction")&&string.IsNullOrWhiteSpace(reason))throw new ArgumentException("A reason is required.");using(var c=DbConnection.Open())using(var tx=c.BeginTransaction()){try{int ver,year,sid;string current,roll;using(var x=DbConnection.Command("SELECT A.CorrectionVersion,A.[Year],A.StudentId,A.Status,S.UniversityRollNo FROM Applications A INNER JOIN Students S ON A.StudentId=S.StudentId WHERE A.ApplicationId=?",c,id)){x.Transaction=tx;using(var r=x.ExecuteReader()){if(!r.Read())throw new ArgumentException("Application not found.");ver=Convert.ToInt32(r[0]);year=Convert.ToInt32(r[1]);sid=Convert.ToInt32(r[2]);current=Convert.ToString(r[3]);roll=Convert.ToString(r[4]);}}if(current=="Rejected"||current=="Approved")throw new InvalidOperationException("This application is already final.");if(status=="Document Verification")using(var x=DbConnection.Command("UPDATE Documents SET VerificationStatus=?,VerifiedAt=? WHERE ApplicationId=?",c,"Verified",DateTime.Now,id)){x.Transaction=tx;x.ExecuteNonQuery();}if(status=="Payment Verification")using(var x=DbConnection.Command("UPDATE Payments SET PaymentStatus=?,VerifiedBy=?,VerifiedAt=? WHERE ApplicationId=?",c,"Verified","admin",DateTime.Now,id)){x.Transaction=tx;x.ExecuteNonQuery();}if(status=="Approved"){object badDocs;using(var x=DbConnection.Command("SELECT COUNT(*) FROM Documents WHERE ApplicationId=? AND VerificationStatus<>'Verified'",c,id)){x.Transaction=tx;badDocs=x.ExecuteScalar();}object pay;using(var x=DbConnection.Command("SELECT COUNT(*) FROM Payments WHERE ApplicationId=? AND PaymentStatus='Verified' AND PaidAmount=RequiredAmount",c,id)){x.Transaction=tx;pay=x.ExecuteScalar();}if(Convert.ToInt32(badDocs)>0||Convert.ToInt32(pay)==0)throw new InvalidOperationException("Verify all documents and payment before approval.");if(year==1&&string.IsNullOrWhiteSpace(roll)){using(var x=DbConnection.Command("UPDATE Counters SET CounterValue=CounterValue+1 WHERE CounterKey='RollNumber'",c)){x.Transaction=tx;x.ExecuteNonQuery();}int n;using(var x=DbConnection.Command("SELECT CounterValue FROM Counters WHERE CounterKey='RollNumber'",c)){x.Transaction=tx;n=Convert.ToInt32(x.ExecuteScalar());}string prefix;using(var x=DbConnection.Command("SELECT SettingValue FROM SystemSettings WHERE SettingKey='RollNumberPrefix'",c)){x.Transaction=tx;prefix=Convert.ToString(x.ExecuteScalar());}roll=prefix+n.ToString("000000");using(var x=DbConnection.Command("UPDATE Students SET UniversityRollNo=? WHERE StudentId=?",c,roll,sid)){x.Transaction=tx;x.ExecuteNonQuery();}}string code="REG-"+DateTime.Now.Year+"-"+Guid.NewGuid().ToString("N").Substring(0,10).ToUpperInvariant();using(var x=DbConnection.Command("INSERT INTO StudentCards (StudentId,ApplicationId,RegistrationCode,IssuedAt) VALUES (?,?,?,?)",c,sid,id,code,DateTime.Now)){x.Transaction=tx;x.ExecuteNonQuery();}}string sql="UPDATE Applications SET Status=?,LastUpdated=?,CorrectionReason=?,RejectReason=?,ApprovedDate=?,RejectedDate=? WHERE ApplicationId=?";using(var x=DbConnection.Command(sql,c,status,DateTime.Now,status=="Needs Correction"?reason:(object)DBNull.Value,status=="Rejected"?reason:(object)DBNull.Value,status=="Approved"?DateTime.Now:(object)DBNull.Value,status=="Rejected"?DateTime.Now:(object)DBNull.Value,id)){x.Transaction=tx;x.ExecuteNonQuery();}History(c,tx,id,ver,status,status,reason,"");tx.Commit();}catch{tx.Rollback();throw;}}}
 }
 public class ReportQuery { public DataTable Registration(){return new ApplicationQuery().All("");} public DataTable Refunds(){return QueryUtil.Table("SELECT A.ApplicationNo,S.StudentName,P.PaidAmount,R.RefundEligibility,R.RefundAmount,R.RefundReason,R.RefundStatus,R.RefundDate,R.RefundReference FROM ((Refunds R INNER JOIN Applications A ON R.ApplicationId=A.ApplicationId) INNER JOIN Students S ON A.StudentId=S.StudentId) INNER JOIN Payments P ON R.PaymentId=P.PaymentId");} }
 public class PaymentQuery { public DataTable ForApplication(int aid){return QueryUtil.Table("SELECT PaymentId,RequiredAmount,PaidAmount,PaymentMethod,TransactionId,PaymentDate,ReceiptFilePath,PaymentStatus,VerifiedBy,VerifiedAt FROM Payments WHERE ApplicationId=?",aid);} public void Verify(int aid,string status){QueryUtil.Execute("UPDATE Payments SET PaymentStatus=?,VerifiedBy=?,VerifiedAt=? WHERE ApplicationId=?",status,"admin",DateTime.Now,aid);} }
 public class DocumentQuery { public DataTable ForApplication(int id){return QueryUtil.Table("SELECT DocumentId,DocumentType,FileName,FilePath,FileSize,VerificationStatus,AdminNote,UploadedAt,VerifiedAt FROM Documents WHERE ApplicationId=?",id);} public void Verify(int id,string status,string note){QueryUtil.Execute("UPDATE Documents SET VerificationStatus=?,AdminNote=?,VerifiedAt=? WHERE DocumentId=?",status,note,DateTime.Now,id);} }
 public class RefundQuery { public DataTable All(){return new ReportQuery().Refunds();} public void Change(int id,string status){QueryUtil.Execute("UPDATE Refunds SET RefundStatus=?,RefundDate=?,ProcessedBy=? WHERE RefundId=?",status,DateTime.Now,"admin",id);} }
 public class StudentAdminQuery { public DataTable All(){return QueryUtil.Table("SELECT StudentId,StudentName,NRC,Phone,Email,UniversityRollNo,Major,[Year],AcademicYear,ProfilePhotoPath,[Address],IsActive,CreatedAt FROM Students ORDER BY IsActive DESC,StudentName");}public void Save(int id,string name,string nrc,string phone,string email,string roll,string major,int year,string academic,string address){if(string.IsNullOrWhiteSpace(name)||string.IsNullOrWhiteSpace(roll))throw new ArgumentException("Student name and university roll number are required.");if(id==0)QueryUtil.Execute("INSERT INTO Students (StudentName,NRC,Phone,Email,UniversityRollNo,Major,[Year],AcademicYear,[Address],IsActive,CreatedAt) VALUES (?,?,?,?,?,?,?,?,?,?,?)",name,nrc,phone,email,roll,major,year,academic,address,true,DateTime.Now);else QueryUtil.Execute("UPDATE Students SET StudentName=?,NRC=?,Phone=?,Email=?,UniversityRollNo=?,Major=?,[Year]=?,AcademicYear=?,[Address]=? WHERE StudentId=?",name,nrc,phone,email,roll,major,year,academic,address,id);}public void SetActive(int id,bool active){QueryUtil.Execute("UPDATE Students SET IsActive=? WHERE StudentId=?",active,id);} }
 public class DataManagementQuery { public DataTable Load(string table){switch(table){case "Students":return new StudentAdminQuery().All();case "Parents":return QueryUtil.Table("SELECT * FROM Parents");case "Guardians":return QueryUtil.Table("SELECT * FROM Guardians");case "Applications":return new ApplicationQuery().All("");case "Documents":return QueryUtil.Table("SELECT D.DocumentId,A.ApplicationNo,D.DocumentType,D.FileName,D.FilePath,D.FileType,D.VerificationStatus,D.AdminNote,D.UploadedAt FROM Documents D INNER JOIN Applications A ON D.ApplicationId=A.ApplicationId");case "Payments":return QueryUtil.Table("SELECT P.PaymentId,A.ApplicationNo,P.PaymentMethod,P.RequiredAmount,P.PaidAmount,P.TransactionId,P.PaymentDate,P.ReceiptFilePath,P.PaymentStatus FROM Payments P INNER JOIN Applications A ON P.ApplicationId=A.ApplicationId");case "Admission List":return new AdmissionQuery().All();case "Semester Results":return new ResultQuery().All();case "Refunds":return new RefundQuery().All();default:return new DataTable();}} }
}
